// Stage 1: compute per-feature mean and biased variance.
// Grid: (num_features,), Block: (BLOCK_SIZE,)
// Each block owns one feature column and streams the batch dimension.
// -----------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void bn_stats_kernel(
    const float* __restrict__ input,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    const int batch_size,
    const int num_features)
{
    const int f = blockIdx.x;
    if (f >= num_features) return;

    const int tid = threadIdx.x;
    float s = 0.f, s2 = 0.f;

    // Vectorised load: process 4 elements per iteration when possible
    const int vec_limit = (batch_size / 4) * 4;
    const float4* in4 = reinterpret_cast<const float4*>(input + f);
    // stride in float4 units along batch: input is [batch, feat] row-major
    // row b -> input[b*num_features + f], so each float4 step = 4*num_features floats
    // We'll fall back to scalar to keep indexing simple and safe.
    for (int b = tid; b < batch_size; b += BLOCK_SIZE) {
        float v = input[b * num_features + f];
        s  += v;
        s2 += v * v;
    }

    // Warp reduction
    #pragma unroll
    for (int off = WARP_SIZE/2; off > 0; off >>= 1) {
        s  += __shfl_down_sync(0xffffffff, s,  off);
        s2 += __shfl_down_sync(0xffffffff, s2, off);
    }

    __shared__ float ws[BLOCK_SIZE / WARP_SIZE];
    __shared__ float ws2[BLOCK_SIZE / WARP_SIZE];
    const int warp_id = tid / WARP_SIZE;
    const int lane    = tid % WARP_SIZE;
    const int nwarps  = BLOCK_SIZE / WARP_SIZE;

    if (lane == 0) { ws[warp_id] = s; ws2[warp_id] = s2; }
    __syncthreads();

    if (tid < nwarps) { s = ws[tid]; s2 = ws2[tid]; }
    else              { s = 0.f;     s2 = 0.f; }

    if (warp_id == 0) {
        #pragma unroll
        for (int off = nwarps/2; off > 0; off >>= 1) {
            s  += __shfl_down_sync(0xffffffff, s,  off);
            s2 += __shfl_down_sync(0xffffffff, s2, off);
        }
    }

    if (tid == 0) {
        float mean = s / batch_size;
        float var  = s2 / batch_size - mean * mean;
        mean_out[f] = mean;
        var_out[f]  = var;
    }
}

// -----------------------------------------------------------------------
// Stage 2: update running stats, then apply BN + GELU + ReLU in one pass.
// Grid: (num_features,), Block: (BLOCK_SIZE,)
// -----------------------------------------------------------------------
template <int BLOCK_SIZE>
__global__ void bn_apply_gelu_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias_bn,
    const float* __restrict__ mean_in,       // per-feature mean (from stage 1 or running)
    const float* __restrict__ var_in,        // per-feature biased var (stage 1) or running var
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    const int batch_size,
    const int num_features,
    const bool training,
    const float momentum,
    const float eps)
{
    const int f = blockIdx.x;
    if (f >= num_features) return;

    const int tid = threadIdx.x;

    // One thread updates the running stats to avoid redundant work.
    float mean_val, inv_std;
    if (tid == 0) {
        mean_val = mean_in[f];
        float var_val = var_in[f];
        if (training) {
            float unbiased = var_val * (float)batch_size / (float)(batch_size - 1);
            running_mean[f] = (1.f - momentum) * running_mean[f] + momentum * mean_val;
            running_var[f]  = (1.f - momentum) * running_var[f]  + momentum * unbiased;
