        inv_std = rsqrtf(var_val + eps);
    }

    // Broadcast mean and inv_std to all threads via shared memory.
    __shared__ float smean, sinv_std;
    if (tid == 0) { smean = mean_val; sinv_std = inv_std; }
    __syncthreads();
    mean_val = smean;
    inv_std  = sinv_std;

    const float gamma = weight[f];
    const float beta  = bias_bn[f];
    const float scale = gamma * inv_std;
    const float shift = beta - gamma * inv_std * mean_val;

    // Apply: normalise -> affine -> GELU -> ReLU
    for (int b = tid; b < batch_size; b += BLOCK_SIZE) {
        float v = input[b * num_features + f];
        float a = v * scale + shift;
        // GELU tanh approximation (matches PyTorch default)
        float g = a * 0.5f * (1.f + tanhf(0.7978845608f * (a + 0.044715f * a * a * a)));
        output[b * num_features + f] = fmaxf(g, 0.f);
    }
