// Warp reduction using xor butterfly
__device__ __forceinline__ float warp_reduce_sum_xor(float val) {
    val += __shfl_xor_sync(0xffffffff, val, 16);
    val += __shfl_xor_sync(0xffffffff, val,  8);
    val += __shfl_xor_sync(0xffffffff, val,  4);
    val += __shfl_xor_sync(0xffffffff, val,  2);
    val += __shfl_xor_sync(0xffffffff, val,  1);
    return val;
}

// Stats kernel: one block per feature, computes mean and variance
template <int BLOCK_SIZE>
__global__ void bn_stats_kernel(
    const float* __restrict__ input,
    float* __restrict__ mean_out,
    float* __restrict__ var_out,
    const int batch_size,
    const int num_features)
{
    const int f = blockIdx.x;
    if (f >= num_features) return;

    const int tid = threadIdx.x;
    const int nwarps = BLOCK_SIZE / WARP_SIZE;
    const int warp_id = tid / WARP_SIZE;
    const int lane = tid % WARP_SIZE;

    float s = 0.f, s2 = 0.f;

    // Process 4 elements per iteration (manual unroll for ILP)
    const int stride4 = BLOCK_SIZE * 4;
    int b = tid * 4;
    for (; b + stride4 - 4 * BLOCK_SIZE + 4 * tid < batch_size * 4; b += stride4) {
        // Each iter covers 4 consecutive batch indices starting at b/4
        // Rewrite: iterate tid, tid+BLOCK, tid+2*BLOCK, tid+3*BLOCK per round
        // Standard loop is cleaner:
        break;
    }
    // Standard scalar loop with unroll hint
    #pragma unroll 4
    for (int bi = tid; bi < batch_size; bi += BLOCK_SIZE) {
        float v = input[bi * num_features + f];
        s  += v;
        s2 += v * v;
    }

    // Warp reduce
    s  = warp_reduce_sum_xor(s);
    s2 = warp_reduce_sum_xor(s2);

    __shared__ float ws[BLOCK_SIZE / WARP_SIZE];
    __shared__ float ws2[BLOCK_SIZE / WARP_SIZE];

    if (lane == 0) {
        ws[warp_id]  = s;
        ws2[warp_id] = s2;
    }
    __syncthreads();

    // Final reduce across warps using first warp
    if (warp_id == 0) {
        s  = (lane < nwarps) ? ws[lane]  : 0.f;
        s2 = (lane < nwarps) ? ws2[lane] : 0.f;
        s  = warp_reduce_sum_xor(s);
        s2 = warp_reduce_sum_xor(s2);
        if (lane == 0) {
            float mean = s / batch_size;
            float var  = s2 / batch_size - mean * mean;
            mean_out[f] = mean;
            var_out[f]  = var;
        }
    }
}

// Apply kernel: one block per feature, applies BN affine + GELU + ReLU
// Training path reads from pre-computed mean/var buffers.
// Eval path reads directly from running_mean/running_var (passed as mean_in/var_in).
template <int BLOCK_SIZE>
__global__ void bn_apply_gelu_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias_bn,
    const float* __restrict__ mean_in,
    const float* __restrict__ var_in,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    const int batch_size,
    const int num_features,
    const bool update_running,
    const float momentum,
    const float eps)
{
    const int f = blockIdx.x;
    if (f >= num_features) return;

    // Precompute scale/shift in shared mem so all threads can reuse
    __shared__ float sscale, sshift;

    if (threadIdx.x == 0) {
        float mean_val = mean_in[f];
        float var_val  = var_in[f];
        if (update_running) {
            float unbiased = var_val * (float)batch_size / (float)(batch_size - 1);
            running_mean[f] = (1.f - momentum) * running_mean[f] + momentum * mean_val;
            running_var[f]  = (1.f - momentum) * running_var[f]  + momentum * unbiased;
        }
        float inv_std = rsqrtf(var_val + eps);
        float gamma   = weight[f];
        float beta    = bias_bn[f];
        sscale = gamma * inv_std;
        sshift = beta - sscale * mean_val;
    }
    __syncthreads();

    const float scale = sscale;
    const float shift = sshift;
    const int tid = threadIdx.x;

    // Process 4 elements per iteration for ILP
    const int stride = BLOCK_SIZE;
    const int b4_end = (batch_size / 4) * 4;

    // Vectorized loop: groups of 4 consecutive batch rows
    // Since input is row-major [batch, features], loading 4 rows for one feature
    // requires 4 separate scalar loads (stride = num_features floats apart).
    // We unroll manually to expose ILP to the compiler.
    for (int b = tid * 4; b + 3 < batch_size; b += stride * 4) {
        float v0 = input[ b      * num_features + f];
        float v1 = input[(b + 1) * num_features + f];
        float v2 = input[(b + 2) * num_features + f];
        float v3 = input[(b + 3) * num_features + f];

        float a0 = v0 * scale + shift;
        float a1 = v1 * scale + shift;
        float a2 = v2 * scale + shift;
        float a3 = v3 * scale + shift;

        // GELU: 0.5 * x * (1 + erf(x / sqrt(2)))
        float g0 = 0.5f * a0 * (1.0f + erff(a0 * 0.7071067811865475f));
        float g1 = 0.5f * a1 * (1.0f + erff(a1 * 0.7071067811865475f));
        float g2 = 0.5f * a2 * (1.0f + erff(a2 * 0.7071067811865475f));
        float g3 = 0.5f * a3 * (1.0f + erff(a3 * 0.7071067811865475f));

        output[ b      * num_features + f] = fmaxf(g0, 0.f);
        output[(b + 1) * num_features + f] = fmaxf(g1, 0.f);
        output[(b + 2) * num_features + f] = fmaxf(g2, 0.f);
        output[(b + 3) * num_features + f] = fmaxf(g3, 0.f);
    }

    // Tail: handle remaining elements
    const int tail_start_block = (batch_size / (stride * 4)) * (stride * 4);
    for (int b = tail_start_block + tid; b < batch_size; b += stride) {
        float v = input[b * num_features + f];
        float a = v * scale + shift;
        float g = 0.5f * a * (1.0f + erff(a * 0.7071067811865475f));
        output[b * num_features + f] = fmaxf(g, 0.f);
    }
}

