    }
    __syncthreads();

    if (warp_id == 0) {
        s  = (lane < nwarps) ? ws[lane]  : 0.f;
        s2 = (lane < nwarps) ? ws2[lane] : 0.f;
        s  = warp_reduce_sum_xor(s);
        s2 = warp_reduce_sum_xor(s2);
        if (lane == 0) {
            float mean = s / (float)batch_size;
            float var  = s2 / (float)batch_size - mean * mean;
            mean_out[f] = mean;
            var_out[f]  = var;
        }
    }
}

// Apply kernel: one block per feature
// Reads precomputed mean/var, applies BN affine, GELU (exact erf form), ReLU.
// Optionally updates running stats (training path).
__global__ void bn_apply_gelu_relu_kernel(
    const float* __restrict__ input,
    float* __restrict__ output,
    const float* __restrict__ weight,
    const float* __restrict__ bias_bn,
    const float* __restrict__ mean_in,
    const float* __restrict__ var_in,
    float* __restrict__ running_mean,
    float* __restrict__ running_var,
    const int batch_size,
    const int num_features,
    const bool update_running,
    const float momentum,
    const float eps)
{
    const int f = blockIdx.x;
    if (f >= num_features) return;

    __shared__ float sscale, sshift;

    if (threadIdx.x == 0) {
        float mean_val = mean_in[f];
        float var_val  = var_in[f];
        if (update_running) {
            float unbiased = var_val * (float)batch_size / (float)(batch_size - 1);
            running_mean[f] = (1.f - momentum) * running_mean[f] + momentum * mean_val;
            running_var[f]  = (1.f - momentum) * running_var[f]  + momentum * unbiased;
        }
        float inv_std = rsqrtf(var_val + eps);
        float gamma   = weight[f];
        float beta    = bias_bn[f];
        sscale = gamma * inv_std;
        sshift = beta - sscale * mean_val;
    }
    __syncthreads();

    const float scale = sscale;
    const float shift = sshift;
    const float ISQRT2 = 0.7071067811865475f;

    const int tid   = threadIdx.x;
    const int BLOCK = blockDim.x;

    // Unrolled-by-4 loop: each thread handles 4 batch rows per iteration
    int bi = tid;
    const int limit4 = batch_size - 3 * BLOCK;
    for (; bi < limit4; bi += BLOCK * 4) {
        float v0 = input[ bi           * num_features + f];
        float v1 = input[(bi +   BLOCK) * num_features + f];
        float v2 = input[(bi + 2*BLOCK) * num_features + f];
        float v3 = input[(bi + 3*BLOCK) * num_features + f];

        float a0 = v0 * scale + shift;
        float a1 = v1 * scale + shift;
        float a2 = v2 * scale + shift;
        float a3 = v3 * scale + shift;

        float g0 = 0.5f * a0 * (1.0f + erff(a0 * ISQRT2));
        float g1 = 0.5f * a1 * (1.0f + erff(a1 * ISQRT2));
        float g2 = 0.5f * a2 * (1.0f + erff(a2 * ISQRT2));
        float g3 = 0.5f * a3 * (1.0f + erff(a3 * ISQRT2));

        output[ bi           * num_features + f] = fmaxf(g0, 0.f);
        output[(bi +   BLOCK) * num_features + f] = fmaxf(g1, 0.f);
        output[(bi + 2*BLOCK) * num_features + f] = fmaxf(g2, 0.f);
        output[(bi + 3*BLOCK) * num_features + f] = fmaxf(g3, 0.f);
    }
    // Tail: remaining batch rows
    for (; bi < batch_size; bi += BLOCK) {
        float v = input[bi * num_features + f];
        float a = v * scale + shift;
        float g = 0.5f * a * (1.0f + erff(a * ISQRT2));
        output[bi * num_features + f] = fmaxf(g, 0.f);
    }
}

torch::Tensor fused_bn_gelu_relu(
    torch::Tensor x,
    torch::Tensor weight,
    torch::Tensor bias,
    torch::Tensor running_mean,
    torch::Tensor running_var,
    bool training,
    double momentum,
    double eps)
{
    CHECK_CUDA(x);
    CHECK_CUDA(weight);
    CHECK_CUDA(bias);
    CHECK_CUDA(running_mean);
    CHECK_CUDA(running_var);
    CHECK_CONTIGUOUS(x);
    CHECK_FLOAT(x);
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");

    const int batch_size   = x.size(0);
    const int num_features = x.size(1);

    auto output = torch::empty_like(x);

    // 512 threads for stats kernel to amortize reduction overhead over large batch
    const int STATS_BLOCK  = 512;
    // 256 threads for apply kernel; lower register pressure, better occupancy
    const int APPLY_BLOCK  = 256;
    const int grid = num_features;

    if (training) {
        auto mean_buf = torch::empty({num_features}, x.options());
        auto var_buf  = torch::empty({num_features}, x.options());

        bn_stats_kernel<<<grid, STATS_BLOCK>>>(
            x.data_ptr<float>(),
            mean_buf.data_ptr<float>(),
            var_buf.data_ptr<float>(),
            batch_size,
            num_features);

        bn_apply_gelu_relu_kernel<<<grid, APPLY_BLOCK>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            mean_buf.data_ptr<float>(),
            var_buf.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            batch_size,
            num_features,
            true,
            static_cast<float>(momentum),
            static_cast<float>(eps));
    } else {
        // Eval: skip stats kernel entirely; use running stats directly
        bn_apply_gelu_relu_kernel<<<grid, APPLY_BLOCK>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            weight.data_ptr<float>(),
            bias.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            running_mean.data_ptr<float>(),
            running_var.data_ptr<float>(),
            batch_size,
            num_features,
            false,
            static_cast<float>(momentum),
            static_cast<float>(eps));
    }

    return output;
}
